export type Thread = {
  name: string
  color: string
  createdBy: 'user' | 'agent'
  // hidden from the thread picker, the move picker and the thread view's filter, but
  // kept: its messages keep their tags, and a heading naming it brings it back
  isArchived?: boolean
}

// A row of the main conversation the thread view draws: a person's message or a
// reply's text, as stored, by its row id and the start of its text.
export type ViewRow = {
  id: string
  role: 'user' | 'assistant'
  // the text's start, whitespace dropped: how a transcript row is matched to it
  mark: string
  // the text as the transcript shows it (a person's message as typed, without the
  // notes for the model beside it), so the view does not depend on the conversation
  // a compaction rewrites. Absent on rows kept by an earlier version.
  text?: string
  // the length of the text as typed, where notes for the model follow it in the row
  // (rows of an earlier version, which kept no text)
  typed?: number
  // a reply a tool call followed in its turn: words on the way, not the turn's last
  // reply, so the view leaves it out
  interim?: true
  // the pictures the person pasted with their message, in order
  images?: ViewImage[]
  // the main conversation's token position (TokenPos) as the row's turn ended, and its
  // compaction count then: how far the conversation has moved on since is the gap a
  // thread's summary is for. Absent until the turn ends; a row an earlier version kept
  // is stamped when the session starts.
  pos?: number
  epoch?: number
}

// The main conversation's token position: how many tokens its context (Claude's whole
// transcript as the model is sent it, tool output included) has grown by in all, from the
// context size the engine last reported (none before its first report this run), and how
// many compactions it has been through.
export type TokenPos = {
  pos: number
  last?: number
  epoch: number
}

// A picture the person pasted: its media type, its size where its header tells it, and
// the file Claude Code saved it to, read as the view draws it. Rows kept by an earlier
// version hold its bytes as base64 instead, where they were few enough to draw.
export type ViewImage = {
  type: string
  width?: number
  height?: number
  path?: string
  data?: string
}

// What a small model keeps of one thread: `short`, where it stands, for the note beside
// the person's message; `long`, its history for an agent that forgot it, for the
// read_thread tool; `line`, one line for the person scanning their threads. `coversRow` is
// the thread's last message the summary was made from, at token position `coversPos`.
export type ThreadSummary = {
  name: string
  short?: string
  long?: string
  line?: string
  coversRow?: string
  coversPos?: number
  // when it was made, and when its line was, by the engine's clock
  madeAt?: number
  lineAt?: number
}

// What the summaries' calls have cost in all, as the API counted it, and the characters
// they sent.
export type SummaryUsage = {
  calls: number
  failed: number
  input: number
  output: number
  cacheRead: number
  cacheWrite: number
  chars: number
}

// One summary call as the log keeps it, for debugging: its number in the session (`n`),
// when it started by the engine's clock, what it made (a thread's pack, or one-line
// summaries), why (`trigger`: the turn ending, a thread past a share of the catch-up
// gap, a compaction starting, read_thread), the threads it was for, the model asked, the
// characters sent, its tokens as the API counted them (`isEstimated`: none came back,
// the input guessed from the characters), its cost in dollars at list price (none for a
// model whose price is not known), how long it took, and what came of it (`fallback`:
// the model was refused and the next call asks another; `unparsed`: answered, but not
// in the form asked).
export type SummaryCall = {
  n: number
  at: number
  kind: 'line' | 'pack'
  trigger: string
  threads: string[]
  model: string
  chars: number
  input: number
  cacheRead: number
  cacheWrite: number
  output: number
  isEstimated?: boolean
  cost?: number
  ms: number
  outcome: 'ok' | 'unparsed' | 'empty' | 'error' | 'aborted' | 'refused' | 'fallback'
  why?: string
}

// The totals of a session's summary calls of one kind: estimated tokens left out, so
// they say what was billed; `unpriced` calls are those of a model with no known price.
export type SummaryCallTotals = {
  calls: number
  failed: number
  input: number
  cacheRead: number
  cacheWrite: number
  output: number
  cost: number
  unpriced: number
  ms: number
}

// A session's summary calls: the latest few, and the totals of all of them by kind.
export type SummaryCallLog = { calls: SummaryCall[]; totals: { line: SummaryCallTotals; pack: SummaryCallTotals } }

// Where the threads stood when the model was last told, beside the person's message:
// the merges (a merged-away thread's key -> its thread's key) and the agent switch.
export type Brief = {
  merged: Record<string, string>
  mayCreate: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'thread-chat': {
      // whether threads are on in the session: as the person last chose there with
      // /threads, else as the default; off, the mod leaves the session be
      isOn: boolean
      // the person's own choice in the session, kept over the default; null until they
      // make one
      choice: boolean | null
      // whether threads are on in a session with no choice of its own, as the person
      // last set with /threads default (kept for every session); off until they set it
      isOnByDefault: boolean
      threads: Thread[]
      // a merged-away thread's key -> the key of the thread it now belongs to
      aliases: Record<string, string>
      // whether the agent may start threads (create_thread): `/threads agent`, off at first
      agentMayCreate: boolean
      // whether the chat is filtered to the thread picked above the prompt; off (as at
      // first), the chat shows every row
      filtersChat: boolean
      // a heading's key as typed -> the key of the thread it was decided to mean at send
      snaps: Record<string, string>
      // the main conversation's rows since the person's last message, that message
      // first: each row's id and each tool call's, in the order they were stored
      recent: string[]
      // the start of each reply text in those rows: a screen may know a reply by an
      // id of its own (the desktop's is the API message's), so a reply is matched by text
      recentTexts: string[]
      // the key of the thread picked above the prompt ('' none): where a message with
      // no heading goes. The thread view does not follow it (viewThreads).
      current: string
      // the keys of threads the person deleted: a heading that names one, or a merge or
      // an earlier send that points to one, belongs to no thread. A thread started again
      // by that name takes its key back.
      deleted: string[]
      // a person's message row id -> the key of the thread it went to: sent with no
      // heading while that thread was picked
      sentTo: Record<string, string>
      // `${row id}|${key of the thread a part was first placed in, '' none}` -> the key
      // of the thread the person moved it to ('' none)
      moved: Record<string, string>
      // the open move picker: `${row id}|${key of the thread its part sits in}`; '' none
      picking: string
      // whether the open move picker shows a field for a new thread's name in place
      // of its pills
      naming: boolean
      // moves, archives and deletions to tell the model beside the person's next message
      untold: string[]
      // what the model was last told of the threads; null until it is told how they
      // work (and again after a compaction)
      briefed: Brief | null
      // the person's messages and reply texts as stored, in order: what the thread
      // view draws, each by its transcript row's id
      viewRows: ViewRow[]
      // how many of the thread view's pictures have been read from their files: each
      // one read draws the view again
      picturesRead: number
      // the first of the thread view's sections it draws, by its place among them; null
      // while it draws the newest (as opened, or another pick in its filter)
      viewFrom: number | null
      // what the thread view's own filter picked: the keys of the threads it shows, and
      // '' for the sections of no thread; none, it shows every section
      viewThreads: string[]
      // whether the band shows the field for a new thread's name in place of its `+`
      bandNaming: boolean
      // what each output row of `/threads manage` that draws the threads' panel shows, by
      // its requestId: '' (or none) each thread's merge, archive and delete, `merge:<key>`
      // the threads that one can merge into, `delete:<key>` the question whether to delete
      // it, `done` the row's text again
      manageModes: Record<string, string>
      // whether the thread picker's list is open in the mobile app, which draws no Select:
      // its button opens and closes it
      pickerOpen: boolean
      // the main conversation's token position, kept with the session's record
      tokenPos: TokenPos
      // each thread's summaries by its key, kept in a file beside the view's rows
      summaries: Record<string, ThreadSummary>
      // each thread's one-line summary by its key, and when it was made: what the band and
      // the thread view draw
      summaryLines: Record<string, { line: string; at: number }>
      // what the summaries' calls have cost
      summaryUsage: SummaryUsage
      // each summary call, the latest CALLS_KEPT, for `/thread-view trace summaries`;
      // kept in a file beside the view's rows, read by no render
      summaryCalls: SummaryCallLog
      // whether the agent was offered read_thread this run: only as a run starts, so the
      // tools the model is sent stay the same all session
      readToolOffered: boolean
      // whether this run's session.start has run: one running again is a reload
      hasStarted: boolean
      // whether the band shows a line under its controls with the picked thread's one-line
      // summary (or the active thread's, none picked): `/threads summaries`, off at first,
      // kept with the session's record
      summaryLineShown: boolean
      // the key of the thread the latest turn touched last ('' none yet)
      activeThread: string
      // the mods the welcome line above the prompt was last dismissed with, as this mod's
      // store kept them (hooks/welcome.tsx); written as the session starts, so the other
      // mods know this one is installed
      welcome: { seen: string[] }
    }
  }
}
